    OFF_ED25519,
    OFF_MLDSA_SEED,
    OFF_X25519,
    OFF_MLKEM_SEED,
    ED25519_SK_LEN,
    MLDSA_SEED_LEN,
    X25519_SK_LEN,
    MLKEM_SEED_LEN,
    HALF_ECC,
    HALF_PQC,
    MLKEM_CT_LEN,
    X25519_PT_LEN,
    SS_LEN,
    ED25519_SIG_LEN,
    MLDSA_SIG_LEN,
